public static String appx(String word1, String word2) {
    word1 = word1.toLowerCase();
    word2 = word2.toLowerCase();
    int commonCount = 0;
    boolean[] counted = new boolean[word2.length()];

    for (int i = 0; i < word1.length(); i++) {
        for (int j = 0; j < word2.length(); j++) {
            if (word1.charAt(i) == word2.charAt(j) && !counted[j]) {
                commonCount++;
                counted[j] = true;
                break;
            }
        }
    }

    int sum = word1.length() + word2.length();
    int gcd = gcd(commonCount, sum);

    return "appx(" + word1 + ", " + word2 + ") = " + (commonCount / gcd) + "/" + (sum / gcd);
}

