public static int findSmallestInteger(int n) {
    char[] digits = Integer.toString(n).toCharArray();
    int len = digits.length;

    // Find the first digit that is smaller than the digit next to it
    for (int i = len - 2; i >= 0; i--) {
        if (digits[i] < digits[i + 1]) {
            // Find the smallest digit on the right side of (i-th digit) which is greater than digits[i]
            int minIndex = i + 1;
            for (int j = i + 2; j < len; j++) {
                if (digits[j] > digits[i] && digits[j] < digits[minIndex]) {
                    minIndex = j;
                }
            }

            // Swap the above found smallest digit with digits[i]
            char temp = digits[i];
            digits[i] = digits[minIndex];
            digits[minIndex] = temp;

            // Sort the digits after the (i-th digit) in ascending order
            Arrays.sort(digits, i + 1, len);

            // Return the new number formed
            return Integer.parseInt(new String(digits));
        }
    }

    // If the above loop does not find such a digit, then the given number can't be rearranged
    // to get a greater number
    return -1;
}

