    int x2 = points[1][0];
    int y2 = points[1][1];
    int x3 = points[2][0];
    int y3 = points[2][1];

    int area = x1 * (y2 - y3) + x2 * (y3 - y1) + x3 * (y1 - y2);

    return area != 0;
}

